feature.sample:
CPhotoMode photo;
photo.Enter(game.TimeScale());          // 現在の time_scale を保存
game.SetTimeScale(0.0f);                 // 時間停止 (呼び出し側)
photo.MoveCamera({dx, dy});
photo.ZoomCamera(0.1f);                  // +10%
photo.SetFilter(CPhotoMode::Sepia);
if (input.shutter) photo.RequestCapture();
if (photo.ConsumeCaptureRequest()) SaveScreenshot();
photo.Exit();
game.SetTimeScale(photo.SavedTimeScale());
